package com.campusradar;

import com.campusradar.common.*;
import com.campusradar.social.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.jdbc.datasource.*;
import tools.jackson.databind.json.JsonMapper;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.campusradar.common.SqlRows.map;

class SocialServiceTest {
    JdbcTemplate db; SocialService service; OwnerTransactions tx;
    @BeforeEach void setup(){var ds=new DriverManagerDataSource("jdbc:h2:mem:social;MODE=MySQL;DB_CLOSE_DELAY=-1","sa","");db=new JdbcTemplate(ds);db.execute("DROP ALL OBJECTS");
        db.execute("CREATE TABLE users(id VARCHAR PRIMARY KEY,status VARCHAR,data_operation VARCHAR,data_revision INT DEFAULT 0,display_name VARCHAR,provider_verified BOOLEAN DEFAULT false,provider_verified_until TIMESTAMP,role VARCHAR DEFAULT 'USER',buddy_discoverable BOOLEAN DEFAULT false,preferences VARCHAR DEFAULT '{}')");db.update("INSERT INTO users(id,status,data_operation,display_name) VALUES('u1','ACTIVE','IDLE','Owner'),('u2','ACTIVE','IDLE','Member'),('u3','ACTIVE','IDLE','Other')");
        String base=",version INT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP";
        db.execute("CREATE TABLE buddy_rooms(id VARCHAR PRIMARY KEY,owner_id VARCHAR,name VARCHAR,description VARCHAR,visibility VARCHAR,capacity INT,state VARCHAR"+base+")");db.execute("CREATE TABLE buddy_members(id VARCHAR PRIMARY KEY,room_id VARCHAR,user_id VARCHAR,role VARCHAR,joined_at TIMESTAMP"+base+",UNIQUE(room_id,user_id))");db.execute("CREATE TABLE buddy_tasks(id VARCHAR PRIMARY KEY,room_id VARCHAR,title VARCHAR,question_id VARCHAR,due_at TIMESTAMP"+base+")");db.execute("CREATE TABLE buddy_task_progress(id VARCHAR PRIMARY KEY,room_id VARCHAR,task_id VARCHAR,user_id VARCHAR,completed BOOLEAN"+base+",UNIQUE(task_id,user_id))");db.execute("CREATE TABLE buddy_invitations(id VARCHAR PRIMARY KEY,room_id VARCHAR,inviter_id VARCHAR,invitee_id VARCHAR,state VARCHAR,expires_at TIMESTAMP"+base+")");db.execute("CREATE TABLE posts(id VARCHAR PRIMARY KEY,author_id VARCHAR,body_md VARCHAR,tags VARCHAR,status VARCHAR,published_at TIMESTAMP"+base+")");db.execute("CREATE TABLE post_likes(post_id VARCHAR,user_id VARCHAR,PRIMARY KEY(post_id,user_id))");db.execute("CREATE TABLE comments(id VARCHAR PRIMARY KEY,post_id VARCHAR,experience_id VARCHAR,author_id VARCHAR,parent_id VARCHAR,body VARCHAR,status VARCHAR"+base+")");
        db.execute("CREATE TABLE referrals(id VARCHAR PRIMARY KEY,provider_id VARCHAR,company_id VARCHAR,job_id VARCHAR,title VARCHAR,description VARCHAR,expires_at TIMESTAMP,status VARCHAR"+base+")");db.execute("CREATE TABLE referral_requests(id VARCHAR PRIMARY KEY,referral_id VARCHAR,applicant_id VARCHAR,message VARCHAR,status VARCHAR,reply VARCHAR,consent_at TIMESTAMP"+base+",UNIQUE(referral_id,applicant_id))");
        var rows=new SqlRows(new NamedParameterJdbcTemplate(ds),JsonMapper.builder().build());tx=new OwnerTransactions(rows,new DataSourceTransactionManager(ds));service=new SocialService(rows);
    }
    Object write(String u,java.util.function.Supplier<Object> action){return tx.write(u,"POST","",null,Map.of(),200,false,action);}
    @SuppressWarnings("unchecked") @Test void roomCapacityMembershipAndTaskProgressBelongToActualMember(){var room=(Map<String,Object>)write("u1",()->service.createRoom("u1",map("name","Study","description","","visibility","PUBLIC","capacity",2)));String id=room.get("id").toString();write("u2",()->service.join("u2",id));assertThrows(ApiProblem.class,()->write("u3",()->service.join("u3",id)));var task=(Map<String,Object>)write("u1",()->service.createTask("u1",id,map("title","Review","questionId",null,"dueAt",null)));String taskId=task.get("id").toString();assertThrows(ApiProblem.class,()->write("u3",()->service.progress("u3",id,taskId,true)));write("u2",()->service.progress("u2",id,taskId,true));assertEquals(true,service.tasks("u2",id).getFirst().get("completedByMe"));assertEquals(false,service.tasks("u1",id).getFirst().get("completedByMe"));write("u2",()->service.leave("u2",id));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM buddy_task_progress",Integer.class));}
    @SuppressWarnings("unchecked") @Test void unpublishedPostsCannotBeLikedAndCommentParentMustShareTopic(){var pending=(Map<String,Object>)write("u1",()->service.createPost("u1",map("bodyMd","Draft","tags",List.of())));String id=pending.get("id").toString();assertEquals("PENDING",pending.get("status"));assertThrows(ApiProblem.class,()->write("u2",()->service.like("u2",id,true)));db.update("UPDATE posts SET status='PUBLISHED' WHERE id=?",id);write("u2",()->service.like("u2",id,true));write("u2",()->service.like("u2",id,true));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM post_likes",Integer.class));db.update("INSERT INTO comments(id,post_id,author_id,body,status) VALUES('foreign','other','u1','Hi','PUBLISHED')");assertThrows(ApiProblem.class,()->write("u2",()->service.comment("u2","posts",id,map("body","Reply","parentId","foreign"))));}
    @SuppressWarnings("unchecked") @Test void invitationCannotBeAcceptedByAnotherUserAndOwnerMustCloseBeforeLeaving(){var room=(Map<String,Object>)write("u1",()->service.createRoom("u1",map("name","Private","description","","visibility","INVITE_ONLY","capacity",2)));String id=room.get("id").toString();assertThrows(ApiProblem.class,()->write("u2",()->service.join("u2",id)));var invite=(Map<String,Object>)write("u1",()->service.invite("u1",id,"u2"));assertThrows(ApiProblem.class,()->write("u3",()->service.inviteAction("u3",invite.get("id").toString(),1,"ACCEPT")));write("u2",()->service.inviteAction("u2",invite.get("id").toString(),1,"ACCEPT"));assertThrows(ApiProblem.class,()->write("u1",()->service.leave("u1",id)));write("u1",()->service.close("u1",id,1));write("u1",()->service.leave("u1",id));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM buddy_members WHERE room_id=?",Integer.class,id));}
    @SuppressWarnings("unchecked") @Test void referralRequestIsPrivateAndParticipantsHaveDifferentTransitions(){db.update("UPDATE users SET provider_verified=true,provider_verified_until=DATEADD('DAY',1,CURRENT_TIMESTAMP) WHERE id='u1'");db.update("INSERT INTO referrals(id,provider_id,company_id,title,description,expires_at,status) VALUES('r1','u1','c1','Referral','Details',DATEADD('DAY',1,CURRENT_TIMESTAMP),'PUBLISHED')");var request=(Map<String,Object>)write("u2",()->service.createRequest("u2","r1",map("message","Please consider","consent",true)));String id=request.get("id").toString();assertThrows(ApiProblem.class,()->service.request("u3",id));assertThrows(ApiProblem.class,()->write("u2",()->service.patchRequest("u2",id,map("version",1,"status","ACCEPTED"))));write("u1",()->service.patchRequest("u1",id,map("version",1,"status","ACCEPTED","reply","Welcome")));assertEquals("Welcome",service.request("u2",id).get("reply"));assertThrows(ApiProblem.class,()->write("u2",()->service.patchRequest("u2",id,map("version",2,"status","CANCELLED"))));}
    @Test void expiredProviderVerificationHidesReferral(){db.update("UPDATE users SET provider_verified=true,provider_verified_until=DATEADD('DAY',-1,CURRENT_TIMESTAMP) WHERE id='u1'");db.update("INSERT INTO referrals(id,provider_id,company_id,title,description,expires_at,status) VALUES('r1','u1','c1','Referral','Details',DATEADD('DAY',1,CURRENT_TIMESTAMP),'PUBLISHED')");assertThrows(ApiProblem.class,()->service.referral("r1",true));assertThrows(ApiProblem.class,()->write("u2",()->service.createRequest("u2","r1",map("message","Hi","consent",true))));}

}
